contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        uint256 beforeBalance = address(c).balance;

        bool firstReverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        uint256 afterFirstBalance = address(c).balance;

        bool secondReverted;
        c.sudicideAnyone(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        uint256 afterSecondBalance = address(c).balance;

        assert(firstReverted || (!secondReverted && afterSecondBalance <= beforeBalance));
    }

    receive() external payable {}
}

