// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(uint256 dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        uint256 beforeBalance = address(c).balance;
        bool firstReverted;
        try c.sudicideAnyone() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        uint256 afterFirstBalance = address(c).balance;
        bool secondReverted;
        try c.sudicideAnyone() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint256 afterSecondBalance = address(c).balance;
        assertTrue(firstReverted || (!secondReverted && afterSecondBalance <= beforeBalance));
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
